  // Close mobile menu on route change
  useEffect(() => {
    setIsOpen(false);
  }, [location]);

  return (
    <nav 
      className={`fixed top-0 w-full z-50 transition-all duration-300 ${
        scrolled ? 'py-4' : 'py-6'
      }`}
    >
      <div className="container mx-auto px-6">
        <div 
          className={`glass-panel rounded-full px-6 py-3 flex items-center justify-between transition-all duration-300 ${
            scrolled ? 'bg-opacity-60 shadow-lg shadow-aura-purple/10' : 'bg-opacity-30'
          }`}
        >
          {/* Logo */}
          <Link to="/" className="flex items-center space-x-2 group">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-aura-purple to-aura-magenta flex items-center justify-center group-hover:shadow-[0_0_20px_rgba(124,58,237,0.5)] transition-shadow duration-300">
