            <Link 
              to="/contact"
              className="px-5 py-2 rounded-full text-sm font-semibold text-white bg-white/10 hover:bg-aura-purple hover:shadow-[0_0_25px_rgba(124,58,237,0.6)] border border-white/10 transition-all duration-300 ease-out"
